INSERT INTO acompanhamento (id, aluno_id, turma_id, disciplina_id, bimestre_id, professor_id, descricao, media, status, versao_atual, revisor_id, publicado_em, criado_em, atualizado_em) VALUES
  (12001, 1, 1, 1, 1, 1, 'Em Língua Portuguesa, Mariana apresentou evolução ao longo do bimestre. Ainda oscila em alguns conteúdos, e o acompanhamento da família faz diferença.', 6.8, 'PUBLICADO', 1, 2, '2026-05-03 14:06:00', '2026-04-17 10:56:24', '2026-05-03 14:06:00'),
  (12002, 2, 1, 1, 1, 1, 'Alice teve um desempenho satisfatório em Língua Portuguesa. Compreende os conteúdos principais, mas pode ganhar mais segurança revisando as atividades em casa.', 7.3, 'PUBLICADO', 1, 1, '2026-05-06 14:16:00', '2026-04-15 11:17:53', '2026-05-06 14:16:00'),
  (12003, 3, 1, 1, 1, 1, 'Luana teve um desempenho satisfatório em Língua Portuguesa. Compreende os conteúdos principais, mas pode ganhar mais segurança revisando as atividades em casa.', 6.3, 'PUBLICADO', 1, 2, '2026-05-04 15:51:00', '2026-04-13 15:58:49', '2026-05-04 15:51:00'),
  (12004, 4, 1, 1, 1, 1, 'Henrique precisa de mais atenção em Língua Portuguesa. Tem deixado atividades incompletas; sugerimos uma conversa com a escola para combinarmos estratégias.', 4.8, 'PUBLICADO', 1, 2, '2026-05-03 09:20:00', '2026-04-16 08:59:27', '2026-05-03 09:20:00'),
  (12005, 5, 1, 1, 1, 1, 'Melissa participa das aulas de Língua Portuguesa e cumpre a maior parte das atividades. Recomendamos manter a rotina de estudos para consolidar o que foi aprendido.', 7.7, 'PUBLICADO', 1, 1, '2026-05-04 10:33:00', '2026-04-15 08:35:00', '2026-05-04 10:33:00'),
  (12006, 6, 1, 1, 1, 1, 'Lucas demonstrou excelente desempenho em Língua Portuguesa neste bimestre. Participa das aulas com interesse, realiza as atividades com autonomia e ajuda os colegas sempre que pode.', 8.0, 'PUBLICADO', 1, 1, '2026-05-03 10:47:00', '2026-04-15 15:40:48', '2026-05-03 10:47:00'),
  (12007, 7, 1, 1, 1, 1, 'Em Língua Portuguesa, Theo apresentou evolução ao longo do bimestre. Ainda oscila em alguns conteúdos, e o acompanhamento da família faz diferença.', 6.7, 'PUBLICADO', 1, 2, '2026-05-06 09:14:00', '2026-04-15 18:27:56', '2026-05-06 09:14:00'),
  (12008, 8, 1, 1, 1, 1, 'Pedro teve um desempenho satisfatório em Língua Portuguesa. Compreende os conteúdos principais, mas pode ganhar mais segurança revisando as atividades em casa.', 7.5, 'PUBLICADO', 1, 1, '2026-05-04 16:33:00', '2026-04-19 16:06:12', '2026-05-04 16:33:00'),
  (12009, 9, 1, 1, 1, 1, 'Em Língua Portuguesa, Marina apresentou evolução ao longo do bimestre. Ainda oscila em alguns conteúdos, e o acompanhamento da família faz diferença.', 7.1, 'PUBLICADO', 1, 1, '2026-05-06 09:26:00', '2026-04-14 13:48:29', '2026-05-06 09:26:00'),
  (12010, 10, 1, 1, 1, 1, 'Pedro encontrou dificuldades em Língua Portuguesa neste bimestre. Será encaminhado(a) ao reforço e contamos com a família para acompanhar as tarefas de casa.', 5.7, 'PUBLICADO', 1, 2, '2026-05-06 09:23:00', '2026-04-19 20:14:54', '2026-05-06 09:23:00'),
  (12011, 11, 1, 1, 1, 1, 'Pedro demonstrou excelente desempenho em Língua Portuguesa neste bimestre. Participa das aulas com interesse, realiza as atividades com autonomia e ajuda os colegas sempre que pode.', 8.4, 'PUBLICADO', 1, 1, '2026-05-04 10:17:00', '2026-04-15 15:53:02', '2026-05-04 10:17:00'),
  (12012, 12, 1, 1, 1, 1, 'Lucas encontrou dificuldades em Língua Portuguesa neste bimestre. Será encaminhado(a) ao reforço e contamos com a família para acompanhar as tarefas de casa.', 5.6, 'PUBLICADO', 1, 2, '2026-05-04 16:03:00', '2026-04-16 15:43:49', '2026-05-04 16:03:00'),
  (12013, 13, 1, 1, 1, 1, 'Julia precisa de mais atenção em Língua Portuguesa. Tem deixado atividades incompletas; sugerimos uma conversa com a escola para combinarmos estratégias.', 5.6, 'PUBLICADO', 1, 2, '2026-05-04 11:50:00', '2026-04-15 16:16:53', '2026-05-04 11:50:00'),
  (12014, 14, 1, 1, 1, 1, 'Nicolas participa das aulas de Língua Portuguesa e cumpre a maior parte das atividades. Recomendamos manter a rotina de estudos para consolidar o que foi aprendido.', 6.7, 'PUBLICADO', 1, 2, '2026-05-05 12:53:00', '2026-04-16 13:15:06', '2026-05-05 12:53:00'),
  (12015, 15, 1, 1, 1, 1, 'O desempenho de Helena em Língua Portuguesa ficou abaixo do esperado. Demonstra interesse quando recebe apoio individual, o que indica bom potencial de recuperação.', 5.3, 'PUBLICADO', 1, 2, '2026-05-05 11:14:00', '2026-04-13 12:56:27', '2026-05-05 11:14:00'),
  (12016, 16, 1, 1, 1, 1, 'Em Língua Portuguesa, Vinícius apresentou evolução ao longo do bimestre. Ainda oscila em alguns conteúdos, e o acompanhamento da família faz diferença.', 6.8, 'PUBLICADO', 1, 1, '2026-05-05 15:03:00', '2026-04-13 16:51:19', '2026-05-05 15:03:00'),
  (12017, 17, 1, 1, 1, 1, 'Bernardo precisa de mais atenção em Língua Portuguesa. Tem deixado atividades incompletas; sugerimos uma conversa com a escola para combinarmos estratégias.', 4.4, 'PUBLICADO', 1, 2, '2026-05-03 15:01:00', '2026-04-15 19:31:12', '2026-05-03 15:01:00'),
  (12018, 18, 1, 1, 1, 1, 'Ótimo bimestre de Caio em Língua Portuguesa. Mostrou domínio dos conteúdos trabalhados e boa capacidade de explicar o próprio raciocínio.', 9.7, 'PUBLICADO', 1, 2, '2026-05-05 13:16:00', '2026-04-18 08:51:35', '2026-05-05 13:16:00'),
  (12019, 19, 1, 1, 1, 1, 'Gabriela teve um desempenho satisfatório em Língua Portuguesa. Compreende os conteúdos principais, mas pode ganhar mais segurança revisando as atividades em casa.', 7.2, 'PUBLICADO', 1, 1, '2026-05-06 17:52:00', '2026-04-14 09:47:59', '2026-05-06 17:52:00'),
  (12020, 20, 1, 1, 1, 1, 'Benjamin alcançou os objetivos previstos em Língua Portuguesa com segurança. É organizado(a), entrega as tarefas no prazo e faz perguntas que enriquecem as aulas.', 9.0, 'PUBLICADO', 1, 2, '2026-05-05 13:32:00', '2026-04-16 18:24:22', '2026-05-05 13:32:00'),
  (12021, 1, 1, 2, 1, 4, 'Mariana participa das aulas de Arte e cumpre a maior parte das atividades. Recomendamos manter a rotina de estudos para consolidar o que foi aprendido.', 7.3, 'PUBLICADO', 1, 2, '2026-05-06 11:00:00', '2026-04-13 11:03:16', '2026-05-06 11:00:00'),
